-- Table structure for table `bt_boardroom_bookings`
--

DROP TABLE IF EXISTS `bt_boardroom_bookings`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `bt_boardroom_bookings` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `date` date DEFAULT NULL,
  `start_time` time DEFAULT NULL,
  `end_time` time DEFAULT NULL,
  `bookedby_id` int unsigned DEFAULT NULL,
  `department_id` int unsigned DEFAULT NULL,
  `status_id` int unsigned DEFAULT NULL,
  `no_of_attendees` int DEFAULT NULL,
  `booking_type` int DEFAULT '1',
  `boardroom_name` int DEFAULT '1',
  `notes` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `approvedby_id` int unsigned DEFAULT NULL,
  `response` int DEFAULT '0',
  `status` int DEFAULT '1',
  `subject` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `departments` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `duration` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `bt_boardroom_bookings_bookedby_id_index` (`bookedby_id`),
  KEY `bt_boardroom_bookings_department_id_index` (`department_id`),
  KEY `bt_boardroom_bookings_status_id_index` (`status_id`),
  KEY `bt_boardroom_bookings_created_by_index` (`created_by`),
  KEY `bt_boardroom_bookings_updated_by_index` (`updated_by`),
  KEY `bt_boardroom_bookings_approvedby_id_index` (`approvedby_id`)
) ENGINE=InnoDB AUTO_INCREMENT=79 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

