DROP TABLE IF EXISTS `bt_it_jobs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `bt_it_jobs` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `employee_id` int unsigned DEFAULT NULL,
  `department_id` int unsigned DEFAULT NULL,
  `status_id` int DEFAULT NULL,
  `name` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `expected_date` date DEFAULT NULL,
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `project_id` int unsigned DEFAULT '1',
  `type_id` int unsigned DEFAULT '1',
  `archived` int DEFAULT '0',
  `complet_percentage` int DEFAULT NULL,
  `isagent` int DEFAULT NULL,
  `difficulty` int DEFAULT NULL,
  `responder_id` int unsigned DEFAULT NULL,
  `paymenttype_id` int unsigned DEFAULT NULL,
  `ticketstage_id` int unsigned DEFAULT NULL,
  `assignedto_id` int DEFAULT NULL,
  `completed_date` date DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `bt_it_jobs_employee_id_index` (`employee_id`),
  KEY `bt_it_jobs_department_id_index` (`department_id`),
  KEY `bt_it_jobs_created_by_index` (`created_by`),
  KEY `bt_it_jobs_updated_by_index` (`updated_by`),
  KEY `bt_it_jobs_project_id_index` (`project_id`),
  KEY `bt_it_jobs_type_id_index` (`type_id`),
  KEY `bt_it_jobs_responder_id_index` (`responder_id`),
  KEY `bt_it_jobs_paymenttype_id_index` (`paymenttype_id`),
  KEY `bt_it_jobs_ticketstage_id_index` (`ticketstage_id`)
) ENGINE=InnoDB AUTO_INCREMENT=170 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `bt_it_jobs`
--

LOCK TABLES `bt_it_jobs` WRITE;
