INSERT INTO `bt_it_jobs` VALUES (87,86,10,5,'Trip Sheet Functionality',NULL,'<p>Update the functionality of the Trip sheet</p>',82,82,'2023-09-11 10:43:37','2024-01-22 08:59:49',1,1,1,100,1,2,1,NULL,NULL,NULL,NULL),(88,1,4,5,'WALL OPTIMIZATION','2023-09-05','<p>Please update the database to optimize the wall</p>',82,82,'2023-09-11 10:50:10','2024-01-22 09:00:20',1,1,1,100,0,2,1,NULL,NULL,NULL,NULL),(89,1,2,2,'PRODUCTION WATTS PER HOUR',NULL,'<p>Please include the kilowatts per hour in the production machine</p>',82,82,'2023-09-11 10:55:16','2023-09-19 09:28:34',1,1,0,80,0,3,1,NULL,NULL,NULL,NULL),(90,1,4,5,'CONTROL SHEET TABLET INPUT',NULL,'<p>The input functions to be added on the control sheet for the Tablet</p>',82,82,'2023-09-11 10:59:18','2024-01-22 09:03:27',1,1,1,100,1,1,1,NULL,NULL,NULL,NULL),(91,1,10,5,'ADDING AN OVERVIEW FUNCTION',NULL,'<p>The Quotation, Development and Delivery functions to be added on the overview page.</p>',82,82,'2023-09-11 11:02:07','2024-01-22 09:04:15',1,1,1,100,1,3,1,NULL,NULL,NULL,NULL),(92,82,4,5,'NEW ERP FUNCTION',NULL,'<p>Research further on a new functions to be added onto the ERP system&nbsp;</p>',82,82,'2023-09-11 11:06:02','2024-01-22 13:44:11',1,1,1,100,0,0,1,NULL,NULL,NULL,NULL),(93,1,1,2,'CUSTOMER FUNCTION UPDATE',NULL,'<p>The function will show the customer limit, when creating a quotation.</p>',82,82,'2023-09-11 11:07:59','2023-09-19 09:34:25',1,1,0,60,0,1,1,NULL,NULL,NULL,NULL),(94,1,10,1,'FABRICATION FUNCTION REVIEW',NULL,'<p>Review the fabrication function from the Data which was received from Nikita and follow up if there is a change</p>',82,82,'2023-09-11 11:11:04','2023-09-19 09:36:08',1,1,0,20,0,2,1,NULL,NULL,NULL,NULL),(95,1,4,5,'BT IT POLICY',NULL,'<p>New document for IT Policy needs approval. Commence the policy and change over</p>',82,82,'2023-09-11 11:12:09','2024-01-22 13:44:30',1,1,1,100,1,2,1,NULL,NULL,NULL,NULL),(96,1,1,5,'STOCK TAKE','2023-09-06','<p>Stock taking to be scheduled as per Management directives</p>',82,82,'2023-09-11 11:13:43','2024-01-24 06:09:34',1,1,1,100,0,0,1,NULL,NULL,NULL,NULL),(97,1,4,2,'DOCUMENT TEMPLATE LIBRARY',NULL,'<p>The business in a box concept for BT\'s document template library, to be replicated on Baila ERP to produce a platform where all employees can access version-controlled documents for usage.</p>',82,82,'2023-09-11 11:23:15','2023-09-19 09:37:19',1,1,0,10,1,3,1,NULL,NULL,NULL,NULL),(98,1,4,5,'BT Industrial SITE VISIT',NULL,'<p><span lang=\"EN-GB\">This serves to inform of the</span><span lang=\"EN-GB\">&nbsp;next steps in the process and will need some sample data to assist in preparation of the POC.&nbsp;</span><span lang=\"EN-GB\">Please setup a conference call to discuss the information needed and setup the date for the demo.</span></p><p><span lang=\"EN-GB\">&nbsp;</span></p>',82,82,'2023-09-11 11:27:48','2024-01-24 06:10:02',1,1,1,100,1,2,1,NULL,NULL,NULL,NULL),(99,37,4,2,'PRODUCTION KILOWATT',NULL,'<p>IT to upload the cost and redo reporting as well as the develop ERP page/tab for reporting</p>',82,82,'2023-09-12 13:35:26','2023-09-19 09:37:57',1,1,0,0,1,2,1,NULL,NULL,NULL,NULL),(100,46,4,5,'CONTROL SHEET TABLET INPUT CAPTURE',NULL,'<p>IT to purchase new tablets and follow up on requisitions created for purchase</p>',82,82,'2023-09-12 13:38:21','2024-01-31 08:37:08',1,1,1,100,1,2,1,NULL,NULL,NULL,NULL),(101,37,4,5,'PRODUCTION PLAN UPDATE',NULL,'<p>IT to update the Production Plan parameters of Rand per Kilogram on the system</p>',82,82,'2023-09-12 13:40:15','2023-09-12 13:40:33',1,1,1,0,1,2,NULL,NULL,NULL,NULL,NULL),(102,37,1,2,'CREATE NEW FUNCTION FOR LOGISTICS',NULL,'<p>IT to create a new function for Logistic Overview on quote, production and deliveries</p>',82,82,'2023-09-12 13:43:22','2023-09-19 09:38:57',1,1,0,20,1,3,1,NULL,NULL,NULL,NULL),(103,37,1,6,'CONCESSION AGREEMENT FORM',NULL,'<p>IT team to create a link on the system for clients to complete&nbsp;</p>',82,82,'2023-09-12 13:45:58','2023-09-19 09:39:15',1,1,0,0,1,0,1,NULL,NULL,NULL,NULL),(104,37,4,2,'RED CARD and QUOTATION FUNCTION',NULL,'<p>The function has commenced and it is still under development</p>',82,82,'2023-09-12 13:49:12','2023-09-19 09:39:47',1,1,0,20,1,0,1,NULL,NULL,NULL,NULL),(105,1,4,6,'ChatBot',NULL,'<p>IT to link a WhatsApp business to a chatbot</p>',82,82,'2023-09-12 13:51:10','2023-09-19 09:40:42',1,1,0,10,1,3,1,NULL,NULL,NULL,NULL),(106,82,4,5,'ADD NEW USER','2023-09-14','<p>Add new user at Raw Material, Ntsako Rikhotso as a user and create email address for the new user.</p>',82,82,'2023-09-13 10:30:30','2024-01-22 14:07:06',1,1,1,100,1,2,19,NULL,NULL,NULL,NULL),(107,1,4,6,'TALQUE DATA INPUT',NULL,'<p>To add talque data input as a job card and rate card</p>',82,NULL,'2023-09-19 08:28:12','2023-09-19 08:28:12',1,1,0,0,0,2,82,NULL,NULL,NULL,NULL),(108,37,4,6,'KM\'s Length on Production Report',NULL,'<p>Add the function of calculating the length on the production report</p>',82,NULL,'2023-09-19 09:14:03','2023-09-19 09:14:03',1,1,0,0,1,3,1,NULL,NULL,NULL,NULL),(109,82,4,5,'CREATE AN ERP ACCOUNT FOR NEW USER','2023-09-20','<p>Create an ERP baila account for Mr. Itumeleng Malabye as a new user... Still awaiting ERP permissions confirmations from line supervisor</p>',82,82,'2023-09-19 09:55:10','2024-01-23 11:56:32',1,1,1,100,1,1,37,NULL,NULL,NULL,NULL),(110,82,4,5,'SET UP DESKTOP COMPUTERS AT PRODUCTION DEPARTMENT',NULL,'<p>Install and Configure software on three (3) Desktop computers at Production Department.</p>',82,82,'2023-09-20 05:51:43','2024-01-23 14:07:06',1,1,1,100,1,2,1,NULL,NULL,NULL,NULL),(111,82,4,5,'MIGRATE USERS FROM LAPTOP TO DESKTOP',NULL,'<p>Migrate user profiles from the Laptop workstation to newly installed and configured Desktops</p>',82,82,'2023-09-20 05:53:16','2024-01-23 11:56:57',1,1,1,100,1,2,1,NULL,NULL,NULL,NULL),(112,82,4,5,'CONFIGURE LAPTOP FOR RONNIE NYONI AT LOGISTICS','2023-09-21','<p>Configure the user, Ronnie Nyoni on a Dell Laptop and sign in to Office365 and Baila E