--
-- Table structure for table `bt_logistics_schedules`
--

DROP TABLE IF EXISTS `bt_logistics_schedules`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `bt_logistics_schedules` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `schedule_date` datetime DEFAULT NULL,
  `return_date` datetime DEFAULT NULL,
  `quote_id` int unsigned DEFAULT NULL,
  `vehice_id` int unsigned DEFAULT NULL,
  `department_id` int unsigned DEFAULT NULL,
  `requestedby_id` int unsigned DEFAULT NULL,
  `usagetype_id` int unsigned DEFAULT NULL,
  `addressto` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `notes` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `mileage_start` int DEFAULT NULL,
  `mileage_end` int DEFAULT NULL,
  `driver_id` int unsigned DEFAULT NULL,
  `damages_notes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `trafficoffense_notes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `approve_id` int unsigned DEFAULT NULL,
  `response` int DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `bt_logistics_schedules_quote_id_index` (`quote_id`),
  KEY `bt_logistics_schedules_vehice_id_index` (`vehice_id`),
  KEY `bt_logistics_schedules_department_id_index` (`department_id`),
  KEY `bt_logistics_schedules_requestedby_id_index` (`requestedby_id`),
  KEY `bt_logistics_schedules_usagetype_id_index` (`usagetype_id`),
  KEY `bt_logistics_schedules_created_by_index` (`created_by`),
  KEY `bt_logistics_schedules_updated_by_index` (`updated_by`),
  KEY `bt_logistics_schedules_driver_id_index` (`driver_id`),
  KEY `bt_logistics_schedules_approve_id_index` (`approve_id`)
) ENGINE=InnoDB AUTO_INCREMENT=227 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

