  `comments_bt` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `isresolved` int DEFAULT '0',
  `department_id` int unsigned DEFAULT NULL,
  `comments_risk` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `issue_date` date DEFAULT NULL,
  `mitigation` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `preventive_action` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `shift_affect` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
