--
-- Table structure for table `bt_qc_pipe_reports`
--

DROP TABLE IF EXISTS `bt_qc_pipe_reports`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `bt_qc_pipe_reports` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `date` date DEFAULT NULL,
  `hydrostatic_test` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `hydrostatic_comply` int DEFAULT '0',
  `hydrostatic_test_2` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `hydrostatic_comply_2` int DEFAULT '0',
  `hydrostatic_test_3` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `hydrostatic_comply_3` int DEFAULT '0',
  `thermal_comply` int DEFAULT '0',
  `elongation_comply` int DEFAULT '0',
  `pipebatch` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `pipedescrip_id` int unsigned DEFAULT NULL,
  `jobcard_id` int unsigned DEFAULT NULL,
  `pipe_id` int unsigned DEFAULT NULL,
  `batch_id` int unsigned DEFAULT NULL,
  `datapack_id` int unsigned DEFAULT NULL,
  `iot_comply` int NOT NULL DEFAULT '0',
  `mfi_comply` int NOT NULL DEFAULT '0',
  `mfi` decimal(15,2) DEFAULT '0.00',
  `testing` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `bags` int DEFAULT '0',
  `weight` decimal(15,1) DEFAULT '0.0',
  `damagedbags` decimal(15,1) DEFAULT '0.0',
  `active` int DEFAULT '1',
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `thermal_revision_test` decimal(8,2) DEFAULT '0.00',
  `elongation_at_break_test` decimal(8,2) DEFAULT '0.00',
  `iot` decimal(8,2) DEFAULT '0.00',
  `mfi_post` decimal(8,2) DEFAULT '0.00',
  `coc_pipebatch` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `coc_specifications` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mfi_comply_post` int DEFAULT '0',
  `iot_comply_post` int DEFAULT '0',
  `iot_post` decimal(8,2) DEFAULT '0.00',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `item_id` int unsigned DEFAULT NULL,
  `quote_id` int unsigned DEFAULT NULL,
  `supplier_batch_id` int DEFAULT NULL,
  `testing_oit` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `bt_qc_pipe_reports_pipedescrip_id_index` (`pipedescrip_id`),
  KEY `bt_qc_pipe_reports_jobcard_id_index` (`jobcard_id`),
  KEY `bt_qc_pipe_reports_pipe_id_index` (`pipe_id`),
  KEY `bt_qc_pipe_reports_batch_id_index` (`batch_id`),
  KEY `bt_qc_pipe_reports_datapack_id_index` (`datapack_id`),
  KEY `bt_qc_pipe_reports_created_by_index` (`created_by`),
  KEY `bt_qc_pipe_reports_updated_by_index` (`updated_by`),
  KEY `bt_qc_pipe_reports_item_id_index` (`item_id`),
  KEY `bt_qc_pipe_reports_quote_id_index` (`quote_id`),
  KEY `bt_qc_pipe_reports_supplier_batch_id_index` (`supplier_batch_id`)
) ENGINE=InnoDB AUTO_INCREMENT=149 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
