CREATE TABLE `bt_sales_catalogues` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `description` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `price` decimal(15,2) DEFAULT NULL,
  `active` int NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `supplier_id` int unsigned DEFAULT NULL,
  `supplierprice` decimal(15,2) DEFAULT NULL,
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `supplierstock_id` int unsigned DEFAULT NULL,
  `category_id` int unsigned DEFAULT NULL,
  `product_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `product_id` int unsigned DEFAULT NULL,
  `size` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `qty` int NOT NULL DEFAULT '1',
  `next_price_date` date DEFAULT NULL,
  `imageurl` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `gp` int NOT NULL DEFAULT '25',
  `bt_product_id` int unsigned DEFAULT NULL,
  `bt_unitlength` decimal(15,2) DEFAULT NULL,
  `production_required` int NOT NULL DEFAULT '0',
  `priceperkg` decimal(15,2) DEFAULT NULL,
  `suffix` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `bt_sales_catalogues_created_by_index` (`created_by`),
  KEY `bt_sales_catalogues_updated_by_index` (`updated_by`),
  KEY `bt_sales_catalogues_category_id_index` (`category_id`),
  KEY `bt_sales_catalogues_product_id_index` (`product_id`)
) ENGINE=InnoDB AUTO_INCREMENT=6287 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
