  `updated_at` timestamp NULL DEFAULT NULL,
  `btproduct_id` int unsigned DEFAULT NULL,
  `unitlength` decimal(15,2) DEFAULT NULL,
  `weight` decimal(15,3) DEFAULT NULL,
  `totalweight` decimal(15,3) DEFAULT NULL,
  `priceperkg` decimal(15,2) DEFAULT NULL,
  `priceweightunit` decimal(15,2) DEFAULT NULL,
  `priceweighttotal` decimal(15,2) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=15654 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
