INSERT INTO `janvince_smallcontactform_messages` VALUES (1,'0652265612','vallarymarongwe@gmail.com','The level of professionalism among BT Industrial staff is amazing, actually its second to none. I have no doubt that every time I need HDPE pipes, I wont even look for other suppliers, I will come straight to BT-industrial','{\"companyname\":\"TRN INDUSTRIAL SERVICES\",\"email\":\"vallarymarongwe@gmail.com\",\"contactname\":\"0652265612\",\"q1\":\"Satisfied\",\"q2\":\"Satisfied\",\"q3\":\"Satisfied\",\"q4\":\"Satisfied\",\"q5\":\"Satisfied\",\"q6\":\"Very Satisfied\",\"q7\":\"Satisfied\",\"q8\":\"Satisfied\",\"q9\":\"Very Satisfied\",\"q10\":\"Satisfied\",\"q11\":\"Very Satisfied\",\"q12\":\"Very Satisfied\",\"comments\":\"The level of professionalism among BT Industrial staff is amazing, actually its second to none. I have no doubt that every time I need HDPE pipes, I wont even look for other suppliers, I will come straight to BT-industrial\"}',0,'2020-07-03 13:17:19','2020-08-18 10:27:27','154.66.156.161',NULL,'contactForm'),(2,'Sibongile Ngwenya','sibongile@zijinmining.com','None as of yet.','{\"companyname\":\"Gold Vale Trading and Logistics\",\"email\":\"sibongile@zijinmining.com\",\"contactname\":\"Sibongile Ngwenya\",\"q1\":\"Very Satisfied\",\"q2\":\"Very Satisfied\",\"q3\":\"Very Satisfied\",\"q4\":\"Satisfied\",\"q5\":\"Satisfied\",\"q6\":\"Satisfied\",\"q7\":\"Satisfied\",\"q8\":\"Satisfied\",\"q9\":\"Satisfied\",\"q10\":\"Satisfied\",\"q11\":\"Satisfied\",\"q12\":\"Very Satisfied\",\"comments\":\"None as of yet.\"}',0,'2020-07-09 08:41:24','2020-08-18 10:27:41','41.144.83.83',NULL,'contactForm'),(3,'Sibongile Ngwenya','sibongile@zijinmining.com','The service I received was overwhelming','{\"companyname\":\"Gold Vale Trading and Logistics\",\"email\":\"sibongile@zijinmining.com\",\"contactname\":\"Sibongile Ngwenya\",\"q1\":\"Satisfied\",\"q2\":\"Satisfied\",\"q3\":\"Satisfied\",\"q4\":\"Satisfied\",\"q5\":\"Satisfied\",\"q6\":\"Satisfied\",\"q7\":\"Satisf