INSERT INTO `system_mail_partials` VALUES (1,'Header','header','<tr>\n<td align=\"center\"  style=\"background: #fff\" bgcolor=\"#fff\">\n    <a href=\"{{ url }}\"  target=\"_blank\">\n                    <img class=\"img-fluid\" style=\"border:0px; margin: 20px auto; width: 400px\"  src=\"http://eldtrading.bt-industrial.co.za/themes/erl_theme/assets/images/elderberry_logo.png\" alt=\"{{ appName }}\">\n                  </a>\n</td>\n</tr>\n<tr>\n    <td class=\"header\">\n        {% if url %}\n            <a href=\"{{ url }}\">\n                {{ body }}\n            </a>\n        {% else %}\n            <span>\n                {{ body }}\n            </span>\n        {% endif %}\n    </td>\n</tr>','*** {{ body|trim }} <{{ url }}>',1,'2019-02-19 18:24:45','2024-09-24 17:58:48'),(2,'Footer','footer','<tr>\r\n    <td>\r\n        <table class=\"footer\" align=\"center\" width=\"570\" cellpadding=\"0\" cellspacing=\"0\">\r\n            <tr>\r\n                <td class=\"content-cell\" align=\"center\">\r\n                    {{ body|md_safe }}\r\n                </td>\r\n            </tr>\r\n        </table>\r\n    </td>\r\n</tr>','-------------------\r\n{{ body|trim }}',1,'2019-02-19 18:24:45','2019-02-19 20:16:10'),(3,'Button','button','<table class=\"action\" align=\"center\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\">\n    <tr>\n        <td align=\"center\">\n            <table width=\"100%\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\">\n                <tr>\n                    <td align=\"center\">\n                        <table border=\"0\" cellpadding=\"0\" cellspacing=\"0\">\n                            <tr>\n                                <td>\n                                    <a href=\"{{ url }}\" class=\"button button-{{ type ?: \'primary\' }}\" target=\"_blank\">\n                                        {{ body }}\n                                    </a>\n                                </td>\n                            </tr>\n                        </table>\n                    </td>\n                </tr>\n            </table>\n        </td>\n    </tr>\n</table>','{{ body|trim }} <{{ url }}>',0,'2019-02-19 18:24:45','2019-02-19 18:24:45'),(4,'Panel','panel','<table class=\"panel\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\">\n    <tr>\n        <td class=\"panel-content\">\n            <table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\">\n                <tr>\n                    <td class=\"panel-item\">\n                        {{ body|md_safe }}\n                    </td>\n                </tr>\n            </table>\n        </td>\n    </tr>\n</table>','{{ body|trim }}',0,'2019-02-19 18:24:45','2019-02-19 18:24:45'),(5,'Table','table','<div class=\"table\">\n    {{ body|md_safe }}\n</div>','{{ body|trim }}',0,'2019-02-19 18:24:45','2019-02-19 18:24:45'),(6,'Subcopy','subcopy','<table class=\"subcopy\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\">\n    <tr>\n        <td>\n            {{ body|md_safe }}\n        </td>\n    </tr>\n</table>','-----\n{{ body|trim }}',0,'2019-02-19 18:24:45','2019-02-19 18:24:45'),(7,'Promotion','promotion','<table class=\"promotion\" align=\"center\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\">\n    <tr>\n        <td align=\"center\">\n            {{ body|md_safe }}\n        </td>\n    </tr>\n</table>','{{ body|trim }}',0,'2019-02-19 18:24:45','2019-02-19 18:24:45');
