/*!50001 VIEW `monthly_sales` AS select `q`.`id` AS `quote_id`,concat(monthname(`q`.`created_at`),' ',year(`q`.`created_at`)) AS `q_month`,`q`.`ponumber` AS `ponumber`,`u`.`name` AS `name`,`c`.`company_name` AS `company_name`,`q`.`total` AS `total`,`q`.`totalvat` AS `totalvat`,`q`.`totalincvat` AS `totalincvat`,`q`.`created_at` AS `created_at` from ((`bt_sales_newquote` `q` join `users` `u` on((`u`.`id` = `q`.`user_id`))) join `bt_sales_clients` `c` on((`c`.`id` = `q`.`client_id`))) where ((`q`.`ponumber` is not null) and (`q`.`ponumber` <> '') and (`q`.`total` > 0) and (`q`.`created_at` > '2025-01-01 00:00:00')) order by `q`.`id` desc */;
